package org.eclipse.search.internal.ui;

import org.eclipse.jface.preference.IPreferenceStore;

interface IPreferenceStore {
    void setDefault(String key, boolean value);
}

public class SearchPreferencePage {
    public static final String REMEMBER_LAST_USED_PAGE = "org.eclipse.search.potentialMatch.remember";

    public void initializeDefaults(IPreferenceStore store) {
        store.setDefault(REMEMBER_LAST_USED_PAGE, false);
    }
}

